using Careersity.Application.Abstractions.Authentication;using Careersity.Application.Abstractions.Persistence;using Careersity.Domain.Careers;using Careersity.Domain.Courses;using Careersity.Domain.Enums;using Careersity.Domain.Identity;using Careersity.Domain.LearningResources;using Careersity.Domain.Skills;using Careersity.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Logging;using Microsoft.Extensions.Options;
using Careersity.Infrastructure.Authentication;
namespace Careersity.Infrastructure.Initialization;
public interface IDevelopmentDataSeeder{Task SeedAsync(CancellationToken token=default);}
public sealed class CareersityDataInitializer(ICareersityDbContext db,IPasswordService passwords,IOptions<SeedDataOptions> options,IHostEnvironment environment,ILogger<CareersityDataInitializer> logger):IDevelopmentDataSeeder
{
 public async Task SeedAsync(CancellationToken t=default){var o=options.Value;if(!o.Enabled)return;if(environment.IsProduction()&&!o.AllowInProduction)throw new InvalidOperationException("Seed data is disabled in Production unless SeedData:AllowInProduction is explicitly enabled.");var users=0;users+=await SeedUser(o.IncludeDemoAdministrator,o.AdministratorEmail,o.AdministratorPassword,UserRole.Administrator,t);users+=await SeedUser(o.IncludeDemoLearner,o.LearnerEmail,o.LearnerPassword,UserRole.Learner,t);var curriculum=o.IncludeSampleCurriculum?await Curriculum(t):0;logger.LogInformation("Development seed completed: {UsersCreated} users and {CurriculumRecordsCreated} curriculum roots created",users,curriculum);}
 private async Task<int>SeedUser(bool enabled,string email,string password,UserRole role,CancellationToken t){if(!enabled)return 0;if(string.IsNullOrWhiteSpace(email)||string.IsNullOrWhiteSpace(password))throw new InvalidOperationException($"Enabled demo {role} requires configured email and password.");var normalized=User.NormalizeEmail(email);if(await db.Users.AnyAsync(x=>x.NormalizedEmail==normalized,t))return 0;db.Users.Add(new(email,"Demo",role.ToString(),passwords.Hash(password),role));await db.SaveChangesAsync(t);return 1;}
 private async Task<int>Curriculum(CancellationToken t){if(await db.Careers.AnyAsync(x=>x.Slug=="data-analyst",t))return 0;await using var tx=await db.Database.BeginTransactionAsync(t);var category=await db.CareerCategories.SingleOrDefaultAsync(x=>x.Slug=="data-and-analytics",t);if(category is null){category=new CareerCategory("Data and Analytics","data-and-analytics","Career pathways involving data and analysis.");db.CareerCategories.Add(category);}var career=new Career(category.Id,"Data Analyst","data-analyst","Analyze data to support informed decisions.",estimatedDurationWeeks:24);var skillNames=new[]{("Spreadsheet Analysis","spreadsheet-analysis"),("SQL","sql"),("Statistics","statistics"),("Data Cleaning","data-cleaning"),("Data Visualization","data-visualization"),("Business Communication","business-communication")};var skills=new List<Skill>();foreach(var s in skillNames){var existing=await db.Skills.SingleOrDefaultAsync(x=>x.Slug==s.Item2,t);skills.Add(existing??new Skill(s.Item1,s.Item2,SkillCategory.Technical,"Demonstration curriculum skill."));if(existing is null)db.Skills.Add(skills[^1]);}var providerNames=new[]{("MIT OpenCourseWare","mit-open-courseware"),("Khan Academy","khan-academy"),("freeCodeCamp","freecodecamp"),("YouTube","youtube")};foreach(var p in providerNames)if(!await db.LearningProviders.AnyAsync(x=>x.Slug==p.Item2,t))db.LearningProviders.Add(new LearningProvider(p.Item1,p.Item2,"Original source name; no partnership or endorsement is implied."));var titles=new[]{("Introduction to Data Analysis","introduction-to-data-analysis"),("Spreadsheet Fundamentals","spreadsheet-fundamentals"),("Basic Statistics","basic-statistics"),("SQL Fundamentals","sql-fundamentals"),("Data Cleaning","data-cleaning-course"),("Data Visualization","data-visualization-course"),("Business Analytics","business-analytics"),("Dashboard Design","dashboard-design"),("Data Analyst Capstone Preparation","data-analyst-capstone-preparation")};var courses=new List<Course>();for(var i=0;i<titles.Length;i++){var c=new Course(titles[i].Item1,titles[i].Item2,$"Demonstration course: {titles[i].Item1}.",i<3?CourseDifficulty.Beginner:CourseDifficulty.Intermediate,180);c.AddLesson(new(c.Id,"Course overview","course-overview",LessonContentType.Article,15,0,summary:"Concise demonstration lesson metadata.",isRequired:true));c.AssociateSkill(skills[Math.Min(i,skills.Count-1)].Id,SkillProficiencyLevel.Beginner,true);courses.Add(c);}var pathway=new CareerPathway(career.Id,"Data Analyst Foundations","1.0","Demonstration pathway using externally sourced learning metadata.",true);var levelNames=new[]{"Foundations","Core Tools","Applied Analysis"};for(var levelIndex=0;levelIndex<3;levelIndex++){var level=new PathwayLevel(pathway.Id,levelNames[levelIndex],levelIndex);for(var j=0;j<3;j++)level.AddCourse(courses[levelIndex*3+j].Id,j,true);pathway.AddLevel(level);}db.Careers.Add(career);db.Courses.AddRange(courses);db.CareerPathways.Add(pathway);await db.SaveChangesAsync(t);await tx.CommitAsync(t);return 1;}
}
public sealed class ApplicationStartupInitializer(IServiceProvider services,IOptions<DatabaseOptions> database,InitialAdministratorInitializer administrator,IDevelopmentDataSeeder seeder,ILogger<ApplicationStartupInitializer> logger)
{
 public async Task InitializeAsync(CancellationToken t=default){if(database.Value.ApplyMigrationsOnStartup){var context=Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.GetService<CareersityDbContext>(services)??throw new InvalidOperationException("Database migrations require a configured Careersity database.");await context.Database.MigrateAsync(t);logger.LogInformation("Database migrations applied successfully");}await administrator.InitializeAsync(t);await seeder.SeedAsync(t);}
}
